insert into _ss_c values ($ss${"pricing": {"goldSpotUsdPerOzt": 4178.2, "goldQuoteSource": "gold-api.com", "goldQuoteTimestamp": "2026-09-30T11:21:00Z", "lossFactor": 1.07, "markup": 2.0, "laborUsd": 250.55, "chainGPerInch14K": 0.0942, "status": "PROVISIONAL", "methodology": "Estimated grams (charm + findings + 1.0 mm cable chain per inch, 14K, density-scaled for 10K/18K) x spot per gram x karat fineness x 1.07, plus labor from the owner's 14K enamel bracelet quote; list price = 2 x cost rounded up to USD 10."}, "approval": {"blockers": ["PROVISIONAL PRICE: labor is the enamel bracelet quote; ask the workshop for an anklet quote before pushing to Etsy.", "Grams are geometry estimates (chain g/in scaled from the 1.1 mm FW chain); no sample has been cast or weighed.", "Hero image is a design visualization generated in Higgsfield by the owner; photograph the physical piece before or after the first sale.", "Etsy taxonomy name 'Anklets' (Jewelry root) is not verified against the live tree; the push stops if it is missing or ambiguous."], "etsyDraftCreationAuthorized": true, "livePublicationAuthorized": false, "authority": "Owner instruction 2026-10-01: 40 SS27 anklets approved (direction, 9/10/11 in, provisional FW pricing), panel import \"aktar\"."}, "variantSeal": "d998641bf7b16293acf343d44f23c349"}$ss$::jsonb, $ss$No hero image yet: this charm was not generated in Higgsfield; generate it from hero-prompts.html before pushing.$ss$, $ss$Metal: solid 10K, 14K or 18K gold in yellow, white or rose.$ss$, $ss$Charm: solid gold, sculpted, with a closed back; no enamel.$ss$, $ss$Chain: 1.0 mm solid gold cable chain with spring ring clasp; the charm hangs from a gold jump ring at the centre; choose 9, 10 or 11 inches.$ss$, $ss$Fit: measure around the ankle just above the bone and add half an inch to one inch for an easy drape. Most ankles take 9 or 10 inches.$ss$, $ss$Each piece is made to order and ships free within the United States from New Jersey. Add a gift message at checkout and it ships with the piece.$ss$, $ss$Care: enamel is glass fused to gold. It keeps its colour, but it can chip on a hard knock, so take it off for the gym, rinse it in fresh water after the sea or the pool and dry it with a soft cloth.$ss$, $ss$Care: solid gold does not tarnish. Rinse it in fresh water after the sea or the pool and dry it with a soft cloth to keep the polish.$ss$, $ss$The product image is a design visualization of the finished piece; the handmade piece may vary slightly.$ss$);

create temporary table _ss_p on commit drop as
select f.*, 'BAS-SS-' || f.mid as sku,
  case when f.has_img then 'https://amuletta.artifactstudio.info/artifact/ss27-anklets/' || f.mid || '.jpg' end as image_url,
  f.lead || E'\n\n' || f.story || E'\n\n' || c.metal || E'\n' ||
    case when f.gold then c.goldline
         else 'Enamel: kiln-fired vitreous enamel in ' || array_to_string(f.enamel, ' and ') || ', set flush in recessed cells with polished gold rims.' end
    || E'\nSize: charm ' || f.size || E' mm.\n' || c.chain || E'\n' || c.fit || E'\n\n' || c.ship || E'\n\n'
    || case when f.gold then c.care_gold else c.care_en end || E'\n\n' || c.imgline as description,
  f.tags || ARRAY['gold anklet','anklet for women','gift for her'] as all_tags,
  case when f.gold then ARRAY['Solid gold'] else ARRAY['Solid gold','Vitreous enamel'] end as materials,
  case when f.has_img then c.meta
       else jsonb_set(c.meta, '{approval,blockers}', (c.meta #> '{approval,blockers}') || to_jsonb(c.noimg)) end
  || jsonb_build_object(
       'productType', 'anklet', 'listingProtocol', 'anklet', 'protocolVersion', 'etsy-listing-v1',
       'offersPersonalization', false, 'family', f.family, 'modelId', f.mid, 'name', f.name,
       'enamel', to_jsonb(f.enamel), 'goldOnly', f.gold, 'dims', 'charm ' || f.size || ' mm',
       'variationAxes', jsonb_build_array('Karat', 'Metal Color', 'Anklet Length'),
       'sourcePackage', '2026-10-01-artifact-ss27-anklets', 'sourcePackagePath', 'docs/artifact-studio/ss27-anklets',
       'generatorScript', 'docs/artifact-studio/ss27-anklets/gen_migration.py',
       'imageSha256', f.img_sha, 'grams14Ref', f.g14, 'refPriceCents', f.ref_cents, 'weightSource', 'geometry_estimate')
  || case when f.has_img then '{}'::jsonb else jsonb_build_object('missingHero', true) end as meta
from _ss f, _ss_c c;

insert into public.products (
  id, org_id, sku, title, description, tags, materials, status, currency,
  price_cents, quantity, has_variations, image_url, num_images, product_type, listing_metadata
)
select f.pid, '2c254edf-2119-4079-b09e-dc672e32c1f9', f.sku, f.title, f.description, f.all_tags, f.materials, 'draft', 'USD',
  (select min(x) from unnest(f.price_k) x) * 1000, 20, true,
  f.image_url, case when f.has_img then 1 else 0 end, 'anklet', f.meta
from _ss_p f
where not exists (select 1 from public.products p where p.org_id = '2c254edf-2119-4079-b09e-dc672e32c1f9' and (p.sku = f.sku or p.id = f.pid));

insert into public.product_variants (
  org_id, sku, product_id, name, properties, price_cents, quantity, weight_grams, weight_source, active, currency
)
select '2c254edf-2119-4079-b09e-dc672e32c1f9',
  f.sku || '-' || k.k || c.cc || '-' || replace(z.s, ' inches', 'IN'),
  p.id,
  f.name || ': ' || k.k || ' ' || c.cn || ', ' || z.s,
  jsonb_build_object('Karat', k.k, 'Metal Color', c.cn, 'Anklet Length', z.s),
  f.price_k[(k.n - 1) * 3 + z.n] * 1000, 20,
  f.grams[(k.n - 1) * 3 + z.n], 'geometry_estimate', true, 'USD'
from _ss_p f
join public.products p on p.org_id = '2c254edf-2119-4079-b09e-dc672e32c1f9' and p.sku = f.sku and p.etsy_listing_id is null
cross join unnest(ARRAY['10K','14K','18K']) with ordinality k(k, n)
cross join (values ('Y','Yellow Gold'),('W','White Gold'),('R','Rose Gold')) c(cc, cn)
cross join unnest(ARRAY['9 inches','10 inches','11 inches']) with ordinality z(s, n)
on conflict (org_id, sku) do update set
  product_id = excluded.product_id, name = excluded.name, properties = excluded.properties,
  price_cents = excluded.price_cents, quantity = excluded.quantity, weight_grams = excluded.weight_grams,
  weight_source = excluded.weight_source, active = excluded.active, updated_at = now();

insert into public.listing_images (org_id, product_id, url, source, alt, position)
select p.org_id, p.id, p.image_url, 'url', f.title, 0
from _ss_p f
join public.products p on p.org_id = '2c254edf-2119-4079-b09e-dc672e32c1f9' and p.sku = f.sku and p.etsy_listing_id is null
where p.image_url is not null
  and not exists (select 1 from public.listing_images li where li.product_id = p.id and li.url = p.image_url);

commit;
